import { createNodeTestClient } from "../utils/node_client";

describe("[Node.js] in-band JSONEachRow exception row", () => {
  let client: ClickHouseClient;
  beforeEach(async () => { client = createNodeTestClient(); });
  afterEach(async () => { await client.close(); });

  it("stream() should error, not yield the exception row", async () => {
    const rs = await client.query({
      query: `SELECT toInt32(number) AS n,
                     throwIf(number = 10, 'boom') AS e
              FROM system.numbers LIMIT 100`,
      format: "JSONEachRow",
      clickhouse_settings: {
        max_block_size: "1", // force several blocks => HTTP 200 + streamed body
        http_write_exception_in_output_format: true, // the 25.8 default
      },
    });

    let caught: Error | null = null;
    const received: unknown[] = [];
    try {
      for await (const rows of rs.stream<{ n: number }>()) {
        for (const row of rows) received.push(row.json());
      }
    } catch (err) { caught = err as Error; }

    console.log(`rows=${received.length} caught=${caught?.constructor?.name ?? "none"} last=${JSON.stringify(received.at(-1))}`);
    expect(caught).not.toBeNull(); // FAILS
  });

  it("json() should reject, not include the exception row", async () => {
    const rs = await client.query({
      query: `SELECT toInt32(number) AS n,
                     throwIf(number = 10, 'boom') AS e
              FROM system.numbers LIMIT 100`,
      format: "JSONEachRow",
      clickhouse_settings: {
        max_block_size: "1",
        http_write_exception_in_output_format: true,
      },
    });

    let caught: Error | null = null;
    let rows: unknown[] = [];
    try { rows = await rs.json<{ n: number }>(); } catch (err) { caught = err as Error; }

    console.log(`json rows=${rows.length} caught=${caught?.constructor?.name ?? "none"} last=${JSON.stringify(rows.at(-1))}`);
    expect(caught).not.toBeNull(); // FAILS
  });
});
```

### Expected behaviour

Both calls reject with a `ClickHouseError` carrying code `395` and the server message, the same way they do on 25.11+ servers that send the tagged `__exception__` frame. The error row is never delivered as data.

### Actual behaviour

Both tests fail on `expect(caught).not.toBeNull()` — no error is raised. Console output from the run:

```
rows=8      caught=none last={"exception":"Code: 395. DB::Exception: boom: while executing 'FUNCTION throwIf(equals(__table1.number, 10_UInt8) :: 4, 'boom'_String :: 2) -> throwIf(equals(__table1.number, 10_UInt8), 'boom'_String) UInt8 : 0'. (FUNCTION_THROW_IF_VALUE_IS_NON_ZERO) (version 26.9.19.9 (official build))"}
json rows=11 caught=none last={"exception":"Code: 395. DB::Exception: boom: ... (FUNCTION_THROW_IF_VALUE_IS_NON_ZERO) (version 26.9.19.9 (official build))"}
```

The query actually failed (`system.query_log` has `type = ExceptionWhileProcessing`, `exception_code = 395`), but the caller sees a short, apparently successful result plus one `{ exception: "..." }` row.

### Suggested fix

- [`packages/client-node/src/result_set.ts`](https://github.com/ClickHouse/clickhouse-js/blob/main/packages/client-node/src/result_set.ts#L224-L280) — the `toRows` `Transform`: the only mid-stream error check is the `exceptionTag` / `\r` branch. For `JSONEachRow`-family formats, also treat a row that parses to an object with exactly one key, `exception`, whose value is a string, as a server error: raise a `ClickHouseError` (code parsed from the `Code: NNN.` prefix) through the transform callback, after having delivered the preceding rows.
- [`packages/client-web/src/result_set.ts`](https://github.com/ClickHouse/clickhouse-js/blob/main/packages/client-web/src/result_set.ts#L159-L210) has the same structure and the same gap (not separately measured, code-level only).

Contrast cases that must keep working:
- a genuine result column named `exception`: `SELECT 'boom' AS exception FORMAT JSONEachRow` produces `{"exception":"boom"}`, which is shape-identical — so the check should be scoped (e.g. only when the first row's key set differs, or only for the final row of the body);
- a schema with an `exception` column among others — every row then has all the keys, so a single-key check does not fire.

