import { parseColumnType } from "@clickhouse/client-common";

describe("DateTime64 malformed precision", () => {
  it("should reject DateTime64(10)", () => {
    console.log("RESULT 1:", JSON.stringify(parseColumnType("DateTime64(10)")));
    expect(() => parseColumnType("DateTime64(10)")).toThrow();
  });

  it("should reject DateTime64(12, 'UTC')", () => {
    console.log("RESULT 2:", JSON.stringify(parseColumnType("DateTime64(12, 'UTC')")));
    expect(() => parseColumnType("DateTime64(12, 'UTC')")).toThrow();
