  const typeName = await q(`SELECT toTypeName(CAST(1 AS Enum8(${label} = 1))) FORMAT TabSeparatedRaw`);
  // The bytes the server actually stores for the label:
  const server = await q(`SELECT hex(toString(CAST(1 AS Enum8(${label} = 1))))`);
