// The random strings compress poorly, so the server sends 200 OK before the error occurs.
const QUERY = `SELECT number, randomPrintableASCII(200) AS s,
                      throwIf(number = 1000000, 'boom') AS e
               FROM system.numbers`;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

it("mid-stream server error with a reader that waits 5 ms every 10 batches", async () => {
  const client = createClient({ url: "http://127.0.0.1:8123" });
  for (let run = 1; run <= 5; run++) {
    let rows = 0;
    try {
      const rs = await client.query({ query: QUERY, format: "JSONEachRow" });
      const reader = rs.stream().getReader();
      for (let i = 0; ; i++) {
        const { done, value } = await reader.read();
        if (done) break;
        rows += value.length;
        if (i % 10 === 0) await sleep(5);
      }
      console.log(`run ${run}: no error, ${rows} rows`);
    } catch (e) {
      const err = e as Error;
      console.log(`run ${run}: ${rows} rows, ${err.constructor.name}: ${err.message.split("\n")[0]}`);
    }
  }
  await client.close();
});
